class Solution:
    def smallestK(self, arr: List[int], k: int) -> List[int]:
        arr.sort()
        return arr[:k]

impl Solution {
  pub fn smallest_k(mut arr: Vec<i32>, k: i32) -> Vec<i32> {
    arr.sort();
    arr[..k as usize].to_vec()
  }
}

const smallestK = (arr: number[], k: number): number[] => {
  arr.sort((a, b) => a - b);
  return arr.slice(0, k);
};
